// WebClient implementuje AutoCloseable - uzywamy go w
// try-with-resources, zeby zawsze zwolnic zasoby po zakonczeniu pracy.
// Domyslnie HtmlUnit probuje wykonywac CSS i JavaScript strony, co
// bywa powolne i zawodne - do prostego scrapowania statycznej tresci
// HTML wylaczamy to jawnie.

try (WebClient webClient = new WebClient()) {
    webClient.getOptions().setCssEnabled(false);
    webClient.getOptions().setJavaScriptEnabled(false);
    webClient.getOptions().setTimeout(5000); // 5 sekund - nie czekamy w nieskonczonosc

    HtmlPage page = webClient.getPage("https://example.com");
    System.out.println(page.getTitleText());
}

// getAnchors() zwraca wszystkie znaczniki <a> (linki) na stronie
// jako liste HtmlAnchor - mozna odczytac ich tekst (getTextContent)
// oraz docelowy adres (getHrefAttribute).

var anchors = page.getAnchors();
for (HtmlAnchor anchor : anchors) {
    System.out.println("\"" + anchor.getTextContent().trim() + "\" -> " + anchor.getHrefAttribute());
}

